		/** 
		 * Tests creating a new Report.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Report");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Report" );

			try {            
				Report entity = ReportService.getReportInstance().createReport( generateNewEntity() );
				thePrimaryKey = entity.getReportId();
				LOGGER.info( "-- Successfully created a Report with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Report. 
		 */
		public Report testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Report" );

			Report entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Report with primary key" );
			msg.append( thePrimaryKey );
			
			ReportFetchOneSummary fetchOneSummary = new ReportFetchOneSummary( thePrimaryKey );

			try {
				entity = ReportService.getReportInstance().getReport( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Report " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Report.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Report." );

			StringBuilder msg = new StringBuilder( "Failed to update a Report : " );        
			Report entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Report." );

				// for use later on...
				thePrimaryKey = entity.getReportId();

				ReportService proxy = ReportService.getReportInstance();            
				proxy.updateReport( entity );   

				LOGGER.info( "-- Successfully saved Report - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Report.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Report." );

			try{
			    Report entity = testRead(); 
				ReportService.getReportInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Report with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Report with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Reports.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Reports:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Report : " );        
			List<Report> collection  = null;

			try {
				// call the static get method on the ReportService
				collection = ReportService.getReportInstance().getAllReport();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Report entity = null;            
					Iterator<Report> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getReportId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		ReportTest
		 */
		public ReportTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Report
		 * 
		 * @return Report
		 */
		protected Report generateNewEntity() {
			Report entity = new Report( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  new URL(),  null,  null,  null,  ReportType.values()[0] );
			
			return( entity );
		}

